import assert from'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';
const base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:18996',out=process.env.KLINK_TEST_OUTPUT||'outputs/mobile-keyboard-20261101/local',route='/#learner/chapters/writing/paper-dictation/route-delen.alfa-b~words-2?level=alfa-b&help=practice';mkdirSync(out,{recursive:true});const checks=[],native=[],errors=[];
function instrument(){const viewport=new EventTarget();viewport.height=innerHeight;viewport.offsetTop=0;Object.defineProperty(window,'visualViewport',{configurable:true,value:viewport});window.setTestKeyboard=(height,top=0)=>{viewport.height=height;viewport.offsetTop=top;viewport.dispatchEvent(new Event('resize'));viewport.dispatchEvent(new Event('scroll'));};if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.ended=[];window.addEventListener('klink-audio-source',e=>{const a=e.detail;a.volume=0;if(a.observed)return;a.observed=true;a.addEventListener('ended',()=>window.ended.push(a.src));});}
async function measure(p){await p.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));return p.evaluate(()=>{const viewport=window.visualViewport,main=document.querySelector('.learner-main'),top=viewport.offsetTop,bottom=top+viewport.height,rect=main.getBoundingClientRect();const controls=['[data-practice-listen]','.cp-text-entry input','[data-practice-check]','[data-practice-next]'].map(selector=>{const e=main.querySelector(selector),r=e.getBoundingClientRect();let clip={top,bottom,left:0,right:innerWidth};for(let a=e.parentElement;a;a=a.parentElement){if(/auto|scroll|hidden|clip/.test(getComputedStyle(a).overflowX+' '+getComputedStyle(a).overflowY)){const q=a.getBoundingClientRect();clip={top:Math.max(clip.top,q.top),bottom:Math.min(clip.bottom,q.bottom),left:Math.max(clip.left,q.left),right:Math.min(clip.right,q.right)};}}return{selector,fullyVisible:r.top>=clip.top-1&&r.bottom<=clip.bottom+1&&r.left>=clip.left-1&&r.right<=clip.right+1,width:r.width,height:r.height};});return{keyboardOpen:main.dataset.keyboardOpen==='true',canvasFollowsViewport:Math.abs(rect.top-top)<1&&Math.abs(rect.height-viewport.height)<1,allControlsReachable:controls.every(c=>c.fullyVisible),targets44:controls.every(c=>c.width>=44&&c.height>=44),noHorizontalScroll:document.documentElement.scrollWidth<=innerWidth+1,progressPreserved:JSON.parse(localStorage.getItem('klink.taalroute.attempts.v1')||'[]').some(a=>a.existing===true),controls};});}
function check(m,label){for(const k of['keyboardOpen','canvasFollowsViewport','allControlsReachable','targets44','noHorizontalScroll','progressPreserved'])assert(m[k],label+' '+k+' '+JSON.stringify(m));}
for(const[engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch();try{
 for(const[width,height,visible,pan]of[[320,568,230,0],[390,844,320,80],[740,390,210,20]])for(const mode of['visual-only','resizes-content'])for(const colorScheme of['light','dark']){
  const p=await browser.newPage({viewport:{width,height},hasTouch:true,colorScheme});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(instrument);await p.addInitScript(()=>{window.Audio=class extends EventTarget{constructor(){super();this.dataset={};}play(){this.t=setTimeout(()=>this.dispatchEvent(new Event('ended')),5);return Promise.resolve();}pause(){clearTimeout(this.t);}};});await p.goto(base+route);await p.locator('.cp-pace-controls').waitFor();await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);await p.getByRole('button',{name:'9 seconden',exact:true}).tap();await p.locator('.cp-text-entry input').fill('fietspad');if(mode==='resizes-content')await p.setViewportSize({width,height:visible});await p.evaluate(([h,t])=>window.setTestKeyboard(h,t),[visible,mode==='visual-only'?pan:0]);
  for(const state of['input','compare','ready']){if(state==='compare')await p.locator('.cp-text-entry input').press('Enter');if(state==='ready')await p.getByRole('button',{name:'Klaar',exact:true}).tap();const m=await measure(p);check(m,engine+' '+width+' '+mode+' '+state);checks.push({engine,width,height,visible,pan:mode==='visual-only'?pan:0,mode,colorScheme,state,...m});}
  if(mode==='visual-only')await p.evaluate(([h,t])=>window.setTestKeyboard(h,t),[visible,pan+24]);check(await measure(p),engine+' viewport pan');if(mode==='resizes-content')await p.setViewportSize({width,height});await p.evaluate(h=>window.setTestKeyboard(h,0),height);await p.waitForFunction(()=>document.querySelector('.learner-main').dataset.keyboardOpen==='false');assert(await p.locator('.cp-pace-controls').isVisible());assert.equal(await p.getByRole('button',{name:'9 seconden',exact:true}).getAttribute('aria-pressed'),'true');await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();assert.notEqual(await p.locator('.learner-main').getAttribute('data-keyboard-open'),'true');assert(await p.locator('.learner-nav').isVisible());assert(await p.locator('.taalroute-header').isVisible());await p.close();console.log(engine,width,mode,colorScheme,'PASS');
 }
 const p=await browser.newPage({viewport:{width:320,height:568},hasTouch:true});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(instrument);await p.goto(base+route);await p.locator('.cp-pace-controls').waitFor();await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);await p.locator('.cp-text-entry input').fill('test zin');await p.evaluate(()=>window.setTestKeyboard(250,30));check(await measure(p),engine+' native input');await p.locator('.cp-text-entry input').press('ArrowLeft');await p.locator('.cp-text-entry input').press('Space');assert.equal(await p.locator('.cp-text-entry input').inputValue(),'test zi n');const n=await p.evaluate(()=>window.ended.length);await p.locator('[data-practice-listen]').tap();await p.waitForFunction(n=>window.ended.length>n,n);check(await measure(p),engine+' native playback');await p.locator('.cp-text-entry input').fill('fietspad');await p.locator('.cp-text-entry input').press('Enter');await p.getByRole('button',{name:'Klaar',exact:true}).waitFor();check(await measure(p),engine+' native compare');await p.getByRole('button',{name:'Klaar',exact:true}).tap();await p.waitForFunction(()=>document.querySelector('[data-practice-ready="true"]'));check(await measure(p),engine+' native ready');await p.locator('[data-practice-next]').tap();await p.waitForFunction(()=>document.querySelector('[data-exercise-id]').getAttribute('data-exercise-id').includes('leesboek'));const stored=await p.evaluate(()=>Object.fromEntries(Object.entries(localStorage).filter(([k])=>k.includes('attempt')||k.startsWith('klink.group.'))));await p.evaluate(()=>window.setTestKeyboard(568,0));await p.reload();await p.locator('.cp-pace-controls').waitFor();for(const[k,v]of Object.entries(stored))assert.deepEqual(JSON.parse(await p.evaluate(k=>localStorage.getItem(k),k)),JSON.parse(v));native.push({engine,nativePlayback:true,inputTyping:true,enter:true,touch:true,progressPreserved:true,keyboardViewportSimulated:true});await p.close();
 }finally{await browser.close();writeFileSync(out+'/keyboard-checks.json',JSON.stringify({checks,native,errors,physicalKeyboardTested:false,nativeScreenKeyboardTested:false,method:'Synthetic VisualViewport resize/scroll plus genuine layout viewport resize in Chromium and WebKit; real audio and original app controls.'},null,2)+'\n');}}
assert.equal(checks.length,72);assert.equal(native.length,2);assert.deepEqual(errors,[]);console.log('PASS 72 open-keyboard states, pan/close/restoration and 2 native audio/input/progress trials');
